//! Incremental SHA-256 with a fixed block and checked encoded bit length.
pub struct Digest { state:[u32;8], block:[u8;64], used:usize, count:u64 }
impl Digest {
 pub fn new()->Self{Self{state:[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19],block:[0;64],used:0,count:0}}
 pub fn update(&mut self,mut data:&[u8])->Result<(),String>{self.count=self.count.checked_add(u64::try_from(data.len()).map_err(|_|"Digest length overflow")?).filter(|n|*n<=u64::MAX/8).ok_or("Digest encoded bit length overflow")?;while !data.is_empty(){let n=(64-self.used).min(data.len());self.block[self.used..self.used+n].copy_from_slice(&data[..n]);self.used+=n;data=&data[n..];if self.used==64{self.compress();self.used=0;}}Ok(())}
 pub fn finish(mut self)->String{self.block[self.used]=0x80;self.used+=1;if self.used>56{self.block[self.used..].fill(0);self.compress();self.block.fill(0);}else{self.block[self.used..56].fill(0);}self.block[56..].copy_from_slice(&(self.count*8).to_be_bytes());self.compress();self.state.iter().map(|n|format!("{n:08x}")).collect()}
 fn compress(&mut self){
 const K:[u32;64]=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
 let mut w=[0u32;64];for i in 0..16{w[i]=u32::from_be_bytes(self.block[i*4..i*4+4].try_into().unwrap());}for i in 16..64{let s0=w[i-15].rotate_right(7)^w[i-15].rotate_right(18)^(w[i-15]>>3);let s1=w[i-2].rotate_right(17)^w[i-2].rotate_right(19)^(w[i-2]>>10);w[i]=w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);}let[mut a,mut b,mut c,mut d,mut e,mut f,mut g,mut x]=self.state;for i in 0..64{let t1=x.wrapping_add(e.rotate_right(6)^e.rotate_right(11)^e.rotate_right(25)).wrapping_add((e&f)^(!e&g)).wrapping_add(K[i]).wrapping_add(w[i]);let t2=(a.rotate_right(2)^a.rotate_right(13)^a.rotate_right(22)).wrapping_add((a&b)^(a&c)^(b&c));x=g;g=f;f=e;e=d.wrapping_add(t1);d=c;c=b;b=a;a=t1.wrapping_add(t2);}for(i,v)in[a,b,c,d,e,f,g,x].iter().enumerate(){self.state[i]=self.state[i].wrapping_add(*v);}
 }
}
#[cfg(test)]mod checks{use super::*;#[test]fn empty_abc_and_boundaries(){assert_eq!(Digest::new().finish(),"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");let mut d=Digest::new();d.update(b"a").unwrap();d.update(b"bc").unwrap();assert_eq!(d.finish(),"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");}#[test]fn encoded_length_refuses_overflow(){let mut d=Digest::new();d.count=u64::MAX/8;assert!(d.update(&[0]).is_err());}}
